parameters.jsCode:
const input = $input.first();

const item = input.json;

let body = item.body || '';

body = body.replace(/\[https?:\/\/[^\]]+\]/g, ' ');
body = body.replace(/https?:\/\/\S+/g, ' ');
body = body.replace(/^\s*>.*$/gm, '');

const replyIndex = body.search(/\nOn .+wrote:\s*/i);

if (replyIndex !== -1) {
  body = body.slice(0, replyIndex);
}

body = body
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [
  {
    json: {
      ...item,
      body
    },

    // keep attachments alive
    binary: input.binary || {}
  }
];

