parameters.jsCode:
const current = $input.first();

const gmail = $('Gmail Trigger').item;

return [
  {
    json: current.json,

    // restore original Gmail attachments
    binary: gmail.binary || {}
  }
];

const input = $input.first();

const j = input.json;

return [
  {
    json: {
      message_id: j.id,
      thread_id: j.threadId,

      sender:
        j.from?.value?.[0]
          ? `${j.from.value[0].address || ''} - ${j.from.value[0].name || ''}`.trim()
          : '',

      Subject: j.subject || '',

      body: j.text || j.html || '',

      timestamp: j.date || new Date().toISOString(),

      attachment_count: Object.keys(input.binary || {}).length
    },

    // THIS preserves the real Gmail attachment files
    binary: input.binary || {}
  }
];

const email = $('Normalize Email').item;

return [
  {
    json: email.json,
    binary: email.binary || {}
  }
];

